import time, threading
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class DebouncedHandler(FileSystemEventHandler):
    def __init__(self, cb, delay):
        self.cb, self.delay, self.timer = cb, delay, None
    def on_any_event(self, event):
        if event.is_directory: return
        if self.timer: self.timer.cancel()
        self.timer = threading.Timer(self.delay, lambda: self.cb(event.src_path))
        self.timer.start()

def on_change(path): print(f"changed: {path}")

obs = Observer()
obs.schedule(DebouncedHandler(on_change, {{debounce_ms}}/1000), "{{watch_path}}", recursive=True)
obs.start()
try:
    while True: time.sleep(1)
except KeyboardInterrupt: obs.stop()
obs.join()
